workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who buys books online"

        bookshop = softwareSystem "Bookshop" "Sells books to customers online" {
            webStore = container "Web Store" "Lets customers browse the catalogue and place orders" "Web application"
            orderProcessor = container "Order Processor" "Processes and fulfils customer orders" "Service"

            customer -> webStore "Browses books and places orders using" "HTTPS/HTML"
            webStore -> orderProcessor "Submits new orders to" "gRPC"
        }
    }

    views {
        systemContext bookshop "SystemContext" {
            include *
            autoLayout
        }
    }
}

